/** Repair instructions for an already-retained automated rule result.
 * These never classify a node, create a finding or establish conformance.
 * References checked against W3C WAI guidance on 2026-10-20.
 */
export function accessibilityCorrectionGuidance(ruleId: string): { steps: string[]; reference: string } | null {
  switch (ruleId) {
    case "image-alt": return {
      steps: [
        "Locate the reported selector in DevTools Elements, then find its image component or CMS content entry. Update the source template/content, not only the live DOM; check other instances generated by the same component.",
        'In the image component, add an alt attribute that conveys the image\'s purpose. Use alt="" only for a purely decorative or redundant image.',
        'For an image acting as a link or button, describe its destination or action. Example pattern, not inferred image content: <img src="..." alt="Meaningful description">; replace the example text with an accurate equivalent. Do not use the filename or add redundant aria-labels.',
      ],
      reference: "https://www.w3.org/WAI/tutorials/images/decision-tree/",
    };
    case "label": return {
      steps: [
        "Locate the reported input selector and edit its form component/CMS field template. Keep its existing data binding and validation behavior; generate a unique id for each repeated field instance.",
        "Add a visible label and connect its for attribute to the input's unique id, or use a correctly associated wrapping label.",
        'Example pattern (adapt IDs/text to the reported field): <label for="contact-email">Email address</label><input id="contact-email" type="email">. If existing text supplies the name, reference its id with aria-labelledby. A placeholder or title alone is not a substitute for a persistent visible label.',
      ],
      reference: "https://www.w3.org/WAI/tutorials/forms/labels/",
    };
    case "button-name": return {
      steps: [
        "Locate the reported button selector and edit its source component. Determine its real action from the handler/design before choosing its name; keep the native button semantics and existing handler.",
        "Give the button a meaningful accessible name through its visible text, aria-labelledby or aria-label. Use wording that describes its action.",
        'Prefer visible button text. For an icon-only control, an illustrative pattern is <button type="button" aria-label="Open search">...</button>; use its actual action, not this example by default. Keep decorative icon SVGs aria-hidden="true" and update labels/states when the action changes.',
      ],
      reference: "https://www.w3.org/WAI/ARIA/apg/patterns/button/",
    };
    case "color-contrast": return {
      steps: [
        "Update the foreground/background color pair in the component's CSS or design token. Use the measured and required ratios in the retained evidence to identify the failing pair.",
        "Measure the rendered text against its actual background after the change, including gradients, opacity and relevant UI states. Verify the applicable text-size threshold.",
      ],
      reference: "https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html",
    };
    default: return null;
  }
}

export function accessibilityRemediationVerification(ruleId: string) {
  const manual = ruleId === "label" ? "Click the visible label and confirm it focuses the intended field; check the field's name in the accessibility tree and with a screen reader. Do not submit personal data."
    : ruleId === "button-name" ? "Tab to the button, confirm its announced name describes its action, and test Enter/Space activation in staging without triggering a live transaction."
      : ruleId === "image-alt" ? "Check the image's accessible name/text alternative in context; decorative images should be ignored, while informative and functional images convey the equivalent information or action."
        : "Check the affected component manually against the retained rule guidance, including keyboard and assistive-technology behavior where applicable.";
  return `After publishing the source change and clearing relevant caches, rerun ${ruleId} on every listed selector and other instances of the same component. ${manual} Retain the new automated result and manual check; a passing rule is not a complete accessibility audit.`;
}
